package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class JavaScriptDimFilterExploitTest
{
  @Test
  public void testExploit() throws IOException
  {
    ObjectMapper mapper = new DefaultObjectMapper();
    mapper.setInjectableValues(new InjectableValues.Std().addValue(JavaScriptConfig.class, new JavaScriptConfig(false)));

    String json = "{\n" +
                  "  \"type\": \"javascript\",\n" +
                  "  \"dimension\": \"dim\",\n" +
                  "  \"function\": \"function(x) { return true; }\",\n" +
                  "  \"\": {\n" +
                  "    \"enabled\": true\n" +
                  "  }\n" +
                  "}";

    JavaScriptDimFilter filter = (JavaScriptDimFilter) mapper.readValue(json, DimFilter.class);

    // If the exploit works, we should be able to create a predicate factory (which checks if enabled)
    // Or we can check if it throws an exception when calling toFilter()

    try {
        filter.toFilter();
        // If we reach here, it means JavaScript was enabled (exploit successful) because we injected false.
        Assert.fail("Vulnerability reproduced: JavaScriptDimFilter allowed execution despite JavaScriptConfig(false)");
    } catch (IllegalStateException e) {
        // Expected behavior: JavaScript is disabled
        Assert.assertEquals("JavaScript is disabled", e.getMessage());
    }
  }
}

